examples.code:
MonarchComparisonSection(
    "How it compares",
    eyebrow: "Compare",
    description: "Neutral sample rows for documentation.",
    columns: [
        MonarchComparisonColumn("product", name: "Product A", badge: "This product", isHighlighted: true),
        MonarchComparisonColumn("sheets", name: "Spreadsheets"),
        MonarchComparisonColumn("email", name: "Email threads"),
    ],
    rows: [
        MonarchPricingFeature("history", label: "Change history", values: ["product": true, "sheets": "Per file", "email": false]),
        MonarchPricingFeature("assign", label: "Assign an owner", values: ["product": true, "sheets": false, "email": false]),
        MonarchPricingFeature("roles", label: "Roles and permissions", group: "Access", values: ["product": true, "sheets": "Per file", "email": false]),
        MonarchPricingFeature("export", label: "Export to CSV", group: "Access", values: ["product": true, "sheets": true, "email": false]),
    ],
    bestFor: [
        MonarchComparisonBestFor("product", title: "Product A suits", description: "Teams that share and hand over work every day.", isHighlighted: true),
        MonarchComparisonBestFor("sheets", title: "Spreadsheets suit", description: "One-off lists kept by one person."),
    ],
    note: "Sample note: say when the comparison was checked and against which public sources, and credit trademarks to their owners."
) {
    MonarchButton("Try Product A", variant: .primary) {}
}
